import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static long[] fact;

    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int t = 1;
            while (t-- > 0) {
                String[] input = br.readLine().split(" ");
                int n = Integer.parseInt(input[0]);
                long k = Long.parseLong(input[1]);
                fact = new long[n + 1];
                fact[0] = 1L;
                for (int i = 1; i <= n; i++) {
                    fact[i] = (fact[i - 1] * i) % MOD;
                }
                if (k == 0) {
                    pw.println(fact[n]);
                } else if (k >= n) {
                    pw.println(0);
                } else {
                    int m = (int) k;
                    long sum = 0L;
                    long sign = 1L;
                    int l = n - m;
                    for (int i = 0; i <= l; i++) {
                        long term = (quickPow(l - i, n) * choose(l, l - i)) % MOD;
                        sum = (sum + sign * term + MOD) % MOD;
                        sign *= -1L;
                    }
                    long res = (2L * choose(n, m) * sum) % MOD;
                    pw.println(res);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        pw.close();
    }

    static long choose(int n, int r) {
        if (r == 0 || r == n) return 1L;
        if (r > n || r < 0) return 0L;
        long numerator = fact[n];
        long denominator = (fact[r] * fact[n - r]) % MOD;
        return (numerator * quickPow(denominator, MOD - 2)) % MOD;
    }

    static long quickPow(long base, long exp) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}
